import{_ as n,o as s,c as e,a2 as t}from"./chunks/framework.C3fpVp7C.js";const u=JSON.parse('{"title":"CLI reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference/cli.md","filePath":"reference/cli.md","lastUpdated":1792160181000}'),p={name:"reference/cli.md"};function l(i,a,r,o,d,c){return s(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="cli-reference" tabindex="-1">CLI reference <a class="header-anchor" href="#cli-reference" aria-label="Permalink to &quot;CLI reference&quot;">​</a></h1><p>The <code>agent-auth</code> command runs the server and talks to it. Every command reads its settings from flags or from the environment variables listed below. This page shows the output of <code>agent-auth --help</code>.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>agent-auth: scoped, expiring, auditable credentials for AI agents</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Usage: agent-auth &lt;command&gt; [options]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Server</span></span>
<span class="line"><span>  serve                      Start the REST server</span></span>
<span class="line"><span>      --port &lt;n&gt;             Port (default 8787, env AGENT_AUTH_PORT)</span></span>
<span class="line"><span>      --host &lt;addr&gt;          Bind address (default 127.0.0.1, env AGENT_AUTH_HOST)</span></span>
<span class="line"><span>      --db &lt;path&gt;            SQLite file (default ./data/agent-auth.db, env AGENT_AUTH_DB)</span></span>
<span class="line"><span>      --key &lt;path&gt;           Signing key file (default ./data/signing-key.pem, env AGENT_AUTH_KEY)</span></span>
<span class="line"><span>      --issuer &lt;url&gt;         Issuer URL placed in tokens (env AGENT_AUTH_ISSUER)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Principal commands (need AGENT_AUTH_ADMIN_TOKEN)</span></span>
<span class="line"><span>  grant                      Delegate scopes to an agent and print its token</span></span>
<span class="line"><span>      --principal &lt;id&gt;       Who delegates (required)</span></span>
<span class="line"><span>      --agent &lt;id&gt;           Who receives the grant (required)</span></span>
<span class="line"><span>      --scope &lt;scope&gt;        Scope, repeatable (required)</span></span>
<span class="line"><span>      --ttl &lt;dur&gt;            Lifetime such as 15m, 1h, 7d (default 1h)</span></span>
<span class="line"><span>      --max-uses &lt;n&gt;         Maximum number of allowed uses</span></span>
<span class="line"><span>  revoke &lt;jti&gt;               Revoke a token and everything derived from it</span></span>
<span class="line"><span>  revoke --grant &lt;id&gt;        Revoke a whole grant</span></span>
<span class="line"><span>  approvals [--status s]     List approval requests (default: pending)</span></span>
<span class="line"><span>  approve &lt;id&gt; | deny &lt;id&gt;   Decide a pending approval</span></span>
<span class="line"><span>  audit log                  Print audit entries</span></span>
<span class="line"><span>  audit verify               Verify the audit hash chain</span></span>
<span class="line"><span>      --db &lt;path&gt;            Read the SQLite file directly instead of the server</span></span>
<span class="line"><span>      --head &lt;hash&gt;          Fail unless this previously anchored head is in the chain</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Agent commands</span></span>
<span class="line"><span>  attenuate                  Derive a narrower token from --token</span></span>
<span class="line"><span>      --scope &lt;scope&gt;        Scope, repeatable (required)</span></span>
<span class="line"><span>      --ttl &lt;dur&gt;            Lifetime, capped at the parent&#39;s expiry</span></span>
<span class="line"><span>      --max-uses &lt;n&gt;         Maximum number of allowed uses</span></span>
<span class="line"><span>      --agent &lt;id&gt;           Sub-agent that receives the token</span></span>
<span class="line"><span>  check                      Ask whether --token permits a request (consumes a use)</span></span>
<span class="line"><span>      --action &lt;a&gt;           Concrete action, for example gmail:send (required)</span></span>
<span class="line"><span>      --resource &lt;r&gt;         Resource, for example acme/widgets</span></span>
<span class="line"><span>      --param &lt;k=v&gt;          Request parameter, repeatable</span></span>
<span class="line"><span>      --amount &lt;amt&gt;         Amount, for example 20USD</span></span>
<span class="line"><span>      --approval &lt;id&gt;        Approved approval id to redeem</span></span>
<span class="line"><span>      --dry-run              Evaluate without consuming a use</span></span>
<span class="line"><span>  inspect                    Decode --token and show its live status</span></span>
<span class="line"><span>  revoke --token &lt;t&gt;         Revoke the presented token and its descendants</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Global options</span></span>
<span class="line"><span>  --url &lt;url&gt;                Server URL (default http://127.0.0.1:8787, env AGENT_AUTH_URL)</span></span>
<span class="line"><span>  --token &lt;t&gt;                Agent token, or @file, or - for stdin (env AGENT_AUTH_TOKEN)</span></span>
<span class="line"><span>  --json                     Print raw JSON</span></span>
<span class="line"><span>  -q, --quiet                Print only the essential value (for example the token)</span></span>
<span class="line"><span>  -h, --help                 Show this help</span></span>
<span class="line"><span>  -v, --version              Print the version</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Exit codes: 0 success or allow, 1 error, 3 deny, 4 approval required.</span></span></code></pre></div><h2 id="exit-codes" tabindex="-1">Exit codes <a class="header-anchor" href="#exit-codes" aria-label="Permalink to &quot;Exit codes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>0</code></td><td>Success, or the request is allowed</td></tr><tr><td><code>1</code></td><td>Error, including usage errors and a tampered audit chain</td></tr><tr><td><code>3</code></td><td>The request is denied, or the token is inactive</td></tr><tr><td><code>4</code></td><td>The request needs a human approval</td></tr></tbody></table>`,5)])])}const g=n(p,[["render",l]]);export{u as __pageData,g as default};
